function [Hdn, nProfile, V, NA] = stepIndexGuide(t, a, nCore, nClad, dz, lambda)
% 스텝 인덱스 도파로의 굴절률 분포, 굴절률 위상 항, V 파라미터
%   t        : 좌표 벡터 [um]  (x, y 공통, 예: linspace(-Lmax, Lmax, N))
%   a        : 코어 반경 [um]
%   nCore    : 코어 굴절률
%   nClad    : 클래딩 굴절률 (= BPM 기준 굴절률 nRef)
%   dz       : step 크기 [um]
%   lambda   : 진공 파장 [um]  (생략 시 1.55 = 1550 nm)
%   Hdn      : step마다 곱하는 굴절률 위상 exp(1j*k0*dn*dz)  (N x N)
%   nProfile : 굴절률 분포 n(x,y)  (N x N)
%   V        : V 파라미터 (규격화 주파수)
    if nargin < 6 || isempty(lambda), lambda = 1.55; end

    [XX, YY] = meshgrid(t, t);
    r = sqrt(XX.^2 + YY.^2);

    k0 = 2*pi / lambda;                     % 진공 파수 [rad/um]

    nProfile = nClad + double(r < a) * (nCore - nClad);
    Hdn      = exp(1j * k0 * (nProfile - nClad) * dz);

    NA = sqrt(nCore^2 - nClad^2);
    V  = (2*pi*a/lambda) * NA;

    struct('NA', NA, 'V', V)

end

function [H, dz] = propKernel(N, dt, dz, lambda, nRef)
% Wide-angle FFT-BPM 전파 커널 (주파수 중심 정렬)
%   N      : 격자 수 (한 변)
%   dx     : 격자 간격 [um]
%   dz     : 전파 step [um]
%   lambda : 파장 [um]     (생략 시 1.55 = 1550 nm)
%   nRef   : 기준 굴절률   (생략 시 1)
    if nargin < 5 || isempty(nRef),   nRef   = 1;    end
    if nargin < 4 || isempty(lambda), lambda = 1.55; end

    k0 = 2*pi*nRef / lambda;               % 매질 포함 파수 [rad/um]

    df = 1 / (N*dt);
    f  = (-N/2 : N/2-1) * df;
    kt = 2*pi*f;
    [ktx, kty] = meshgrid(kt, kt);
    kt2 = ktx.^2 + kty.^2;

    H = exp(-1j * kt2 * dz ./ (sqrt(k0^2 - kt2) + k0));
end

function [xShift, eta] = shiftandcoupling(E1, E2, dt, shiftMax)
% E2를 x방향(열 방향)으로 한 픽셀씩 밀면서 E1과의 결합효율 eta를 계산
%   dt       : 격자 간격 [m]
%   shiftMax : 최대 이동 거리 [um]
    nShift = 0 : round(shiftMax / dt);        % 이동 픽셀 수
    xShift = nShift * dt;                     % 이동 거리 [um]
    eta    = zeros(size(nShift));             % 미리 할당

    for k = 1:numel(nShift)
        E2shifted = circshift(E2, [0, nShift(k)]);
        eta(k)    = etaEVA(E1, E2shifted);
    end
end

% circshift는 끝에서 넘어간 값이 반대편으로 되돌아와요. 빔이 가장자리에서 충분히 떨어져 있으면 문제없지만, 가장자리 근처까지 밀 거라면 0으로 채우는 이동 방식으로 바꾸는 게 안전해요.

function [X, Y, r, t, dt, df, L, N, info] = makeGrid(L,N)
if nargin <1, L=50; end
if nargin <2, N=128; end
dt = 2*L/N;
t = (-N/2:N/2-1)*dt;
df = 1/(2*L);
[X,Y] = meshgrid(t,t);
r = sqrt(X.^2 + Y.^2);
    info = struct('N', N, 'Lmax', max(t), 'dt', dt, 'df', df)
end

function E = Gaussian(x0, y0, w, L, N)
    dt = 2*L/N;
    t = (-N/2:N/2-1)*dt;
    [XX, YY] = meshgrid(t, t);
    R_moved = sqrt((XX-x0).^2+(YY-y0).^2);
        E1 = exp(-R_moved.^2/w^2);
    E = E1;
end

function y = etaEVA(E_1, E_2)
% 두 필드 간 오버랩 효율 (mode overlap / coupling efficiency)
    num = abs(sum(conj(E_1(:)) .* E_2(:)))^2;
    den = sum(abs(E_1(:)).^2) * sum(abs(E_2(:)).^2);
    y = num ./ den;
end
